illustrative=[(str(r['year']),money(r['market']),money(r['live_assessed']),money(r['rental_assessed']),money(r['live_tax']),money(r['rental_tax']),money(r['real_market']),'rtc') for r in annual]
expenses=[(str(r['year']),money(r['insurance']),money(r['water']),money(r['electricity']),money(r['repairs']),money(r['capex']),'insurance') for r in annual]
page('projection.html','Year-by-year outlook','MODEL & METHOD / 03','A 50-year calculation is a scenario, never an official statement of future prices or law.',notice('Two separate layers','Verified household forecast fields below are intentionally blank. The separate synthetic appendix teaches the math using unrelated round-number inputs. Official-context links verify legal concepts only; they do not validate the chosen assumptions or computed future amounts.')+'''<details><summary>Actual household forecast register · 2026–2076 · blank and unverified</summary>'''+table('No household amounts or derived outputs are published',['Year','A market value','A assessed value','A property tax','B assessed / tax','Status','Official context'],history,'unverified')+'''</details><h2>Synthetic annual illustration</h2><p>Assume an unrelated fictional home is worth $1,000,000 in 2026 with $200,000 factored assessment. Home value grows 3%; inflation 2.5%; base assessment grows 2%. Transfer is assumed at the start of 2046 with a full-year tax simplification. The invented family-home allowance is held at $1,000,000, <b>not the actual BOE allowance</b>. Eligible live-in assessment = old factored base + max(0, market − old factored base − allowance). Rental reassessment = market. Thereafter factored bases grow 2%; taxable assessment is the lesser of factored base and market. Tax rate 1.2% is invented; no homeowner exemption, direct charges or prorated supplemental bill is included.</p><p>Real value = nominal value divided by 1.025 to the power of years since 2026. Amounts are computed unrounded, then displayed to $10. A 2% base adjustment is a scenario assumption within the cap, not a guaranteed increase.</p>'''+table('SYNTHETIC · 2026–2076 · no actual property inputs',['Year','Market','Eligible live assessment','Rental assessment','Live tax','Rental tax','Real market (2026 $)','Official legal context'],illustrative,'illustration')+'''<h2>Every operating-cost category, kept separate</h2><p>Same fictional home. Starting annual expenses: insurance $3,000; water $2,000; power $1,000; repairs $6,000; capital work $4,000. Each rises at an invented 2.5%. Insurance and tariffs can rise much faster; see stress cases. These are neither premiums nor verified local costs. Tax is in the prior table; mortgage, waste and other household-specific charges remain unknown.</p>'''+table('SYNTHETIC annual expense illustration · official context is coverage, not price',['Year','Insurance','Water','Power','Repairs','Capital work','Official context'],expenses,'illustration'))

stress_rows=[]
for name,(returns,cpi) in STRESS.items():
    path=investment_path(returns,cpi)
    for yr in (1,10,20,50):
        r=path[yr-1]
        stress_rows.append((name,str(yr),money(r['nominal']),money(r['real']),'sec'))
page('stress.html','When the baseline breaks','BLACK SWAN & REGIME RISK / 04','Uneven inflation, market losses and housing disruptions can overwhelm a smooth average.',table('Historical context · dates and measures must not be mixed',['Episode','Official observation','Relevance / limits','Source'],[
('Great Inflation · 1965–1982','Multiple recessions and energy shocks; inflation exceeded 14% in 1980.','A long low-inflation baseline is not a law of nature. Not a forecast for local expenses.','inflation'),
('Great Recession · 2007–2009','National home prices fell about 30% from mid-2006 to mid-2009; S&P 500 price index fell 57% October 2007 to March 2009.','Different peak/trough windows; not calendar-year returns, not total returns and not specific-property performance.','recession'),
('Historical CPI','Monthly and annual records include inflation and deflation.','CPI is not insurance inflation and not the California house-price index used to adjust the family-home allowance.','cpi')
])+'''<h2>Transparent stress paths</h2><p>Begin with unrelated investment capital of $1,000,000. Smooth reference: 5% effective net return, 2.5% inflation for 50 years. Crash: −40% in year 1, then 5%. Inflation shock: 3% return and 8% inflation for five years, then 5% / 2.5%. Stagnation: 0% for ten years, then 5%, with 2.5% inflation throughout. Late crash: 5% except −40% in year 20; inflation 2.5%. No contributions, withdrawals or separate taxes; returns are assumed net of all tax/fees. <b>These are invented stresses, not historical replays, predictions or probabilities.</b></p>'''+table('SYNTHETIC stress outcomes · real dollars measured at starting purchasing power',['Path','Year','Nominal capital','Real capital','Official risk context'],stress_rows,'illustration')+notice('Sequence-risk distinction','With no cash flows, the same returns in a different order have the same terminal product. Early and late crash paths therefore match at year 50. With tax payments, repairs or withdrawals, sequence matters: selling depressed assets can leave fewer assets to participate in recovery. Do not claim this lump-sum illustration measures withdrawal sequence risk.')+table('Joint shocks to test privately · suggested stresses, not forecasts',['Stress','Explicit proposed test','Decision implication','Official context'],[
('Housing recession','Assume local price −30%, rent −15% and vacancy 20% for two years, simultaneous portfolio −40%.','These magnitudes are invented, not observed local data; do not rely on selling one asset to cover another at peak prices.','recession'),
('Insurance / repair shock','Assume premium doubles; test $100,000 uninsured repair and one year without rent.','Invented amounts; verify exclusions, deductible and temporary-housing/lost-rent coverage.','insurance'),
('Solar / utility regime','Assume no solar cash compensation and a positive import/fixed-charge bill; test panel/inverter replacement separately.','Do not carry today’s estimated credit forward indefinitely.','cpuc'),
('Law / eligibility shock','Remove family-home relief; rerun at full reassessment. Freeze or reduce future estate exclusion in a separate policy stress.','No claim these changes have been enacted or assigned a probability.','boe')
],'illustration'))

process=[
('1','Before transfer','Counsel checks trust funding, title, beneficiaries, relationship, powers, debts, prior gifts and estate inclusion. Separate the Inheritor’s own assets from the Transferor’s estate.','Planning action; trust alone is not tax exemption.','estate'),
('2','At death / immediately','Trustee secures property and documents; contact insurer about occupancy, vacancy and landlord coverage. Preserve records privately.','Practical safeguard, not a quoted statutory deadline.','insurance'),
('3','Trust notification','Determine who must receive statutory notice. Generally serve within 60 days of triggering event, with statutory awareness/vacancy exceptions.','Counsel confirms deadline and service.','trust'),
('4','Inventory and appraisal','Record date-of-death values, liabilities, gifts and potential deductions. Obtain defensible appraisal and review basis consistency.','Alternative valuation requires specific eligibility/election.','basis'),
('5','Assessor reporting','File applicable death/change-in-ownership reports; confirm trust-transfer date, supplemental assessments and deadlines with assessor.','Exact county forms/deadlines not verified here; do not rely on the one-year residence rule for all filings.','boe'),
('6','Within one year if seeking family-home relief','Establish genuine eligible principal residence and file homeowners’ (BOE-266) or disabled-veterans’ exemption BEFORE filing BOE-19-P.','Confirm transferor residence, relationship and continuing use; moving out later cancels exclusion next Jan 1 lien date (date-of-death FMV indexed).','boepub'),
('7','Exclusion claim','BOE Pub. 800-1 says file BOE-19-P within three years or before transfer to third party (or within 6 months of supplemental/escape notice); confirm any late/prospective relief rules.','Distinct from one-year exemption deadline; BOE-266 must be filed first.','boepub'),
('8','Generally nine months after death','Executor reviews Form 706 filing requirement, portability and payment; six-month filing extension may be available.','An extension to file is not automatic permission to delay tax payment.','faq'),
('9','Before distribution / implementation','Reserve for tax and debts; compare real sale offers against verified rental and occupancy budgets. Document beneficiary authority and decision.','Do not distribute liquidity needed for settlement.','estate'),
('10','After implementation / annually','Update coverage, rent compliance, accounting, assessment and portfolio allocation; re-run after legal or economic changes.','Current facts must replace old scenarios.','sec')]
page('process.html','From trust to decision','PRACTICAL ROADMAP / 05','Use Transferor, Trustee and Inheritor as placeholders. Keep personal documents out of a public repository.',table('General sequence · not a substitute for trust-specific legal administration',['Step','Timing','Action','Caution','Official context'],process)+notice('Separate clocks and separate taxes','Date of death, trust distribution and deed recording need not be the same date for tax purposes. Estate tax, capital-gains basis and property-tax reassessment are different systems. Have counsel establish the effective transfer date; do not delay eligibility work until distribution.'))

laws=[
('Federal estate tax · 2026','$15,000,000','Gross estate plus relevant adjusted taxable gifts determines filing; estate deductions/credits determine tax. U.S. citizen/resident rules; nonresident noncitizens differ.','estate'),
('Federal estate tax · 2027','$15,480,000','Published November 5, 2026; not an estimate and not a per-heir exemption.','irs27'),
('Estate scope','Cash, securities, real estate and potentially insurance/trust assets','Already-owned assets of the Inheritor are not automatically the Transferor’s assets; inspect actual interests. No private inventory published.','estate'),
('Portability','Timely Form 706 election generally needed','Do not automatically double the exclusion for a married couple.','faq'),
('California death taxes','No CA estate-tax return for deaths from January 1, 2005','Current Controller guidance; older inheritance-tax administration concerns deaths before June 8, 1982. Future law unknown.','sco'),
('Inherited basis','Generally date-of-death fair market value','Alternate valuation and exceptions apply; adjusted assessment for property tax is NOT the same as income-tax basis.','basis'),
('Trust exception','Some irrevocable grantor-trust property gets no §1014 adjustment','Revenue Ruling 2023-2 concerns assets outside deceased grantor gross estate. Never assume step-up merely because title is in trust.','trustbasis'),
('Prop 13 assessment','Annual factored-base increase capped at 2%','Taxable value generally lower of factored base and market; market recovery from temporary decline can exceed 2%. Reassessment/new construction are separate.','rtc'),
('Prop 19 allowance','$1,044,590 displayed to $10','Rounded public-law amount only. Official legal amount is available at linked notice; use the exact legal figure for filings. Applies February 16, 2025–February 15, 2027; future allowance unknown.','allow'),
('Qualifying family home','Old factored base + max(0, market − old base − applicable allowance)','Requires eligible relationship, transferor/transferee principal residence and claims. No general rental-home exclusion. Continued eligibility matters.','boe'),
('Local tax rate / direct charges','','Not published: city-specific rates and local rent rules are withheld from this public guide. Confirm the applicable tax area and coverage privately from current records.','rtc'),
('Home-sale gain exclusion','Up to $250,000 / $500,000 if qualified','Generally own/use two of five years; not automatic upon inheritance. Depreciation/nonqualified use may affect exclusion.','sell'),
('California capital gains','Taxed at ordinary-income rates + 1% Behavioral Health Services Tax','No lower California capital-gains rate; 1% surtax over $1,000,000 renamed from Mental Health Services Tax for 2025+.','ftb540'),
('Personal SALT itemized cap','$40,000 (2025) / $40,400 (2026); statutory reversion to $10,000 after 2029 unless changed','This is the personal Schedule A itemized limit. Rental expenses follow separate rules and require correct allocation; no personal deduction is assumed.',['sched_a','rent']),
('Rental income','Taxable with qualifying expenses and depreciation','Mixed-use allocation, capital improvements, passive losses and possible NIIT matter. Gross rent is not profit.','rent'),
('Savings insurance','$250,000 per depositor / insured bank / ownership category','Aggregate deposits in same category; investments such as stocks and mutual funds are not FDIC insured.','fdic'),
('Law watch · SB 974','Chaptered September 27, 2026, Chapter 665','Enacted special-needs-trust transfer-medium amendment, not a pending blanket restoration of the old parent-child exclusion. Household relevance unknown; confirm effective application with counsel.','bill'),
('Nov 2026 California ballot (unofficial)','Nov 12 (8:46 p.m.): Prop 3 Yes 60.7%, Prop 40 No 52.4%, Prop 42 Yes 51.4%','No Prop 19 repeal appeared on the Nov 2026 ballot; unofficial until Dec 11 certification. Recheck federal legislation and BOE updates at decision time.','sos26')]
